def fail(message):
    sys.stderr.write('CONFLICTO: '+message+'\n')
    sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/ruta/public_html bash script --check|--apply|--restore [respaldo]\n')
    sys.exit(1)
mode=sys.argv[1]
root_value=os.environ.get('IMPE_CRM_PUBLIC','')
if not root_value: fail('Falta IMPE_CRM_PUBLIC.')
root=Path(root_value).resolve()
if not (root/'index.php').is_file(): fail('No es la raiz del CRM.')
backup_root=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-ventas-resultados-backups'))).resolve()
if backup_root==root or backup_root in root.parents or root in backup_root.parents:
    fail('Respaldos deben estar fuera del sitio.')
def hash_bytes(data): return hashlib.sha256(data).hexdigest()
def file_at(rel):
    p=root/rel
    if p.is_symlink() or not p.is_file() or root not in p.resolve().parents:
        fail('Ruta ausente o enlace prohibido: '+rel)
    return p
def atomic(p,data,perm):
    fd,temp=tempfile.mkstemp(prefix='.impe-ventas-',dir=str(p.parent))
    try:
        os.fchmod(fd,perm)
        with os.fdopen(fd,'wb') as output:
            output.write(data)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temp,str(p))
    finally:
        if os.path.exists(temp): os.unlink(temp)
if mode=='--restore':
    if len(sys.argv)!=3: fail('Indica la ruta del respaldo.')
    backup=Path(sys.argv[2]).resolve()
    if backup_root not in backup.parents or backup.is_symlink(): fail('Respaldo fuera del directorio privado.')
    manifest=backup/'manifest.json'
    if not manifest.is_file(): fail('Manifiesto ausente.')
    rows=json.loads(manifest.read_text(encoding='utf-8'))
    if len(rows)!=len(SPECS) or set(z['path'] for z in rows)!=set(s['path'] for s in SPECS):
        fail('Manifiesto no coincide con la entrega.')
    plan=[]
    for row in rows:
        p=file_at(row['path'])
        raw=(backup/row['backup']).read_bytes()
        current=p.read_bytes()
        if hash_bytes(raw)!=row['original_sha256']: fail('Respaldo alterado: '+row['path'])
        if hash_bytes(current) not in (row['original_sha256'],row['applied_sha256']):
            fail('Archivo modificado despues de publicar: '+row['path'])
        plan.append((p,raw,row['mode'],hash_bytes(current)==row['applied_sha256']))
    for p,raw,perm,needed in plan:
        if needed: atomic(p,raw,perm)
    print('OK: restauracion verificada. BD y grabaciones intactas.')
    sys.exit(0)
if len(sys.argv)!=2: fail('Parametros no previstos.')
plan=[]
for row in SPECS:
    p=file_at(row['path'])
    raw=p.read_bytes()
    try: data=raw.decode('utf-8')
    except UnicodeDecodeError: fail('PHP/JS no es UTF-8: '+row['path'])
    crlf=b'\r\n' in raw
    normalized=data.replace('\r\n','\n')
    nold=0;nnew=0;other=0
    modified=normalized
    for patch in row['patches']:
        before=patch['from'];after=patch['to']
        a=normalized.count(before);b=normalized.count(after)
        if a==1 and b==0:
            modified=modified.replace(before,after,1);nold+=1
        elif a==0 and b==1:
            nnew+=1
        else:
            other+=1
    if other or (nold and nnew):
        fail('Variante de produccion o parche parcial; no sobrescribir: '+row['path'])
    state='pendiente' if nold else 'actualizado'
    target=(modified.replace('\n','\r\n') if crlf else modified).encode('utf-8')
    plan.append(dict(path=row['path'],file=p,original=raw,target=target,
                     mode=stat.S_IMODE(p.stat().st_mode),state=state))
for row in plan: print(row['path']+': '+row['state'])
count=sum(1 for z in plan if z['state']=='pendiente')
print('Archivos a modificar:',count)
if mode=='--check':
    print('OK: verificacion de solo lectura. No se aplicaron cambios.')
    sys.exit(0)
if not count:
    print('OK: entrega ya instalada. No se realizaron cambios.')
    sys.exit(0)
backup_root.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(str(backup_root),0o700)
backup=Path(tempfile.mkdtemp(prefix='ventas-resultado-sin-end-',dir=str(backup_root)))
os.chmod(str(backup),0o700)
manifest=[]
for i,row in enumerate(plan):
    name='%02d.bak'%i
    target=backup/name
    target.write_bytes(row['original'])
    os.chmod(str(target),0o600)
    manifest.append(dict(path=row['path'],backup=name,mode=row['mode'],
        original_sha256=hash_bytes(row['original']),applied_sha256=hash_bytes(row['target'])))
manifest_file=backup/'manifest.json'
manifest_file.write_text(json.dumps(manifest,indent=2),encoding='utf-8')
os.chmod(str(manifest_file),0o600)
changed=[]
try:
    for row in plan:
        if row['state']!='pendiente':continue
        if row['file'].read_bytes()!=row['original']:
            fail('Cambio concurrente: '+row['path'])
        atomic(row['file'],row['target'],row['mode'])
        changed.append(row)
except BaseException:
    for row in reversed(changed):
        if hash_bytes(row['file'].read_bytes())==hash_bytes(row['target']):
            atomic(row['file'],row['original'],row['mode'])
    raise
print('OK: resultado comercial inmediato publicado. Respaldo:',str(backup))
print('No se modifico BD, extensiones, webhooks, audios ni modulos de Analista/Marketing.')
